#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum PythonFormalRhsToExprState {
    PythonFormalRhsToExprUninitialized,
    PythonFormalRhsToExprReady {
        expr: Rc<GrammarExpr>,
    },
}
impl PythonFormalRhsToExprState {
    pub fn expr(&self) -> Rc<GrammarExpr> {
        match self {
            PythonFormalRhsToExprState::PythonFormalRhsToExprUninitialized => panic!("no expr on unit variant"),
            PythonFormalRhsToExprState::PythonFormalRhsToExprReady { expr: __val, .. } => __val.clone(),
        }
    }
}

pub fn python_formal_rhs_to_grammar_expr(rhs: Rc<Vec<Rc<FormalGrammarSymbol>>>) -> Rc<GrammarExpr> {
    match (*crate::std_algebra::fold_list(rhs, Rc::new(PythonFormalRhsToExprState::PythonFormalRhsToExprUninitialized), |state, sym| {
        let piece = python_formal_symbol_to_grammar_expr(sym);
match (*state.clone()).clone() {
    PythonFormalRhsToExprState::PythonFormalRhsToExprUninitialized => Rc::new(PythonFormalRhsToExprState::PythonFormalRhsToExprReady {
    expr: piece.clone(),
}),
    PythonFormalRhsToExprState::PythonFormalRhsToExprReady { expr: acc, .. } => Rc::new(PythonFormalRhsToExprState::PythonFormalRhsToExprReady {
    expr: Rc::new(GrammarExpr::Sequence {
    left: acc.clone(),
    right: piece.clone(),
}),
}),
}
})).clone() {
    PythonFormalRhsToExprState::PythonFormalRhsToExprUninitialized => python_formal_epsilon_grammar_expr(),
    PythonFormalRhsToExprState::PythonFormalRhsToExprReady { expr: result, .. } => result.clone(),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
